{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS `zouk-wh.MapleMonk.finance_pricemaster_ccogs_retail_ez_History` ( WMS_SKU STRING, ASIN STRING, BAU FLOAT64, NLC FLOAT64, Cost_Price FLOAT64, MRP FLOAT64, snapshot_date DATE, snapshot_timestamp TIMESTAMP, record_hash STRING ); INSERT INTO `zouk-wh.MapleMonk.finance_pricemaster_ccogs_retail_ez_History` ( WMS_SKU, ASIN, BAU, NLC, Cost_Price, MRP, snapshot_date, snapshot_timestamp, record_hash ) WITH Current_Master AS ( SELECT UPPER(TRIM(WMS_SKU)) AS WMS_SKU, UPPER(TRIM(ASIN)) AS ASIN, SAFE_CAST(REGEXP_REPLACE(CAST(BAU AS STRING), r\'[^0-9.]\', \'\') AS FLOAT64) AS BAU, SAFE_CAST(REGEXP_REPLACE(CAST(NLC AS STRING), r\'[^0-9.]\', \'\') AS FLOAT64) AS NLC, SAFE_CAST(REGEXP_REPLACE(CAST(Cost_Price AS STRING), r\'[^0-9.]\', \'\') AS FLOAT64) AS Cost_Price, SAFE_CAST(REGEXP_REPLACE(CAST(MRP AS STRING), r\'[^0-9.]\', \'\') AS FLOAT64) AS MRP FROM `zouk-wh.MapleMonk.finance_pricemaster_ccogs_retail_ez` WHERE ASIN IS NOT NULL ), Hashed_Master AS ( SELECT *, TO_HEX( MD5( CONCAT( COALESCE(ASIN, \'\'), \'|\', COALESCE(CAST(BAU AS STRING), \'\'), \'|\', COALESCE(CAST(NLC AS STRING), \'\'), \'|\', COALESCE(CAST(Cost_Price AS STRING), \'\'), \'|\', COALESCE(CAST(MRP AS STRING), \'\') ) ) ) AS record_hash FROM Current_Master ), Existing_Bootstrap AS ( SELECT DISTINCT ASIN FROM `zouk-wh.MapleMonk.finance_pricemaster_ccogs_retail_ez_History` WHERE snapshot_date = DATE \'2026-08-01\' ) SELECT h.WMS_SKU, h.ASIN, h.BAU, h.NLC, h.Cost_Price, h.MRP, DATE \'2026-08-01\' AS snapshot_date, CURRENT_TIMESTAMP() AS snapshot_timestamp, h.record_hash FROM Hashed_Master h LEFT JOIN Existing_Bootstrap e ON h.ASIN = e.ASIN WHERE e.ASIN IS NULL; INSERT INTO `zouk-wh.MapleMonk.finance_pricemaster_ccogs_retail_ez_History` ( WMS_SKU, ASIN, BAU, NLC, Cost_Price, MRP, snapshot_date, snapshot_timestamp, record_hash ) WITH Current_Master AS ( SELECT UPPER(TRIM(WMS_SKU)) AS WMS_SKU, UPPER(TRIM(ASIN)) AS ASIN, SAFE_CAST( REGEXP_REPLACE( CAST(BAU AS STRING), r\'[^0-9.]\', \'\' ) AS FLOAT64 ) AS BAU, SAFE_CAST( REGEXP_REPLACE( CAST(NLC AS STRING), r\'[^0-9.]\', \'\' ) AS FLOAT64 ) AS NLC, SAFE_CAST( REGEXP_REPLACE( CAST(Cost_Price AS STRING), r\'[^0-9.]\', \'\' ) AS FLOAT64 ) AS Cost_Price, SAFE_CAST( REGEXP_REPLACE( CAST(MRP AS STRING), r\'[^0-9.]\', \'\' ) AS FLOAT64 ) AS MRP FROM `zouk-wh.MapleMonk.finance_pricemaster_ccogs_retail_ez` WHERE ASIN IS NOT NULL ), Hashed_Master AS ( SELECT *, TO_HEX( MD5( CONCAT( COALESCE(ASIN, \'\'), \'|\', COALESCE(CAST(BAU AS STRING), \'\'), \'|\', COALESCE(CAST(NLC AS STRING), \'\'), \'|\', COALESCE(CAST(Cost_Price AS STRING), \'\'), \'|\', COALESCE(CAST(MRP AS STRING), \'\') ) ) ) AS record_hash FROM Current_Master ), Latest_History AS ( SELECT ASIN, record_hash FROM `zouk-wh.MapleMonk.finance_pricemaster_ccogs_retail_ez_History` QUALIFY ROW_NUMBER() OVER ( PARTITION BY ASIN ORDER BY snapshot_date DESC, snapshot_timestamp DESC ) = 1 ) SELECT h.WMS_SKU, h.ASIN, h.BAU, h.NLC, h.Cost_Price, h.MRP, CURRENT_DATE(\'Asia/Kolkata\') AS snapshot_date, CURRENT_TIMESTAMP() AS snapshot_timestamp, h.record_hash FROM Hashed_Master h LEFT JOIN Latest_History l ON h.ASIN = l.ASIN WHERE l.ASIN IS NULL OR h.record_hash != l.record_hash; CREATE TABLE IF NOT EXISTS `zouk-wh.MapleMonk.finance_ccogs_Cocoblu_RZ` ( channel_name STRING, ccogs_date DATE, ccogs FLOAT64 ); MERGE INTO `zouk-wh.MapleMonk.finance_ccogs_Cocoblu_RZ` AS target USING ( WITH Sales_Raw AS ( SELECT UPPER(TRIM(asin)) AS asin, COALESCE( SAFE_CAST(startDate AS DATE), DATE(SAFE_CAST(startDate AS TIMESTAMP)) ) AS start_dt, COALESCE( SAFE_CAST(endDate AS DATE), DATE(SAFE_CAST(endDate AS TIMESTAMP)), SAFE_CAST(startDate AS DATE), DATE(SAFE_CAST(startDate AS TIMESTAMP)) ) AS end_dt, COALESCE(SAFE_CAST(orderedUnits AS FLOAT64), 0) AS orderedUnits, COALESCE(SAFE_CAST(customerReturns AS FLOAT64), 0) AS customerReturns, COALESCE( SAFE_CAST(JSON_VALUE(orderedRevenue, \'$.amount\') AS FLOAT64), 0 ) AS orderedRevenue FROM `MapleMonk.Amazon_RZ_GET_VENDOR_SALES_REPORT` WHERE asin IS NOT NULL QUALIFY ROW_NUMBER() OVER ( PARTITION BY asin, startDate, endDate ORDER BY _airbyte_emitted_at DESC ) = 1 ), Cocoblu_RZ_Sales AS ( SELECT r.asin, d AS Order_Date, r.orderedUnits / n.days AS orderedUnits, r.customerReturns / n.days AS customerReturns, r.orderedRevenue / n.days AS orderedRevenue FROM Sales_Raw r CROSS JOIN UNNEST([STRUCT( GREATEST(DATE_DIFF(r.end_dt, r.start_dt, DAY) + 1, 1) AS days )]) AS n CROSS JOIN UNNEST( GENERATE_DATE_ARRAY( r.start_dt, LEAST(GREATEST(r.end_dt, r.start_dt), CURRENT_DATE(\'Asia/Kolkata\')) ) ) AS d WHERE r.start_dt IS NOT NULL AND d >= DATE \'2026-08-01\' ), Daily_Sales AS ( SELECT Order_Date, Cocoblu_RZ_Sales.asin AS ASIN, SUM(orderedRevenue) AS total_value, SUM(orderedUnits) AS total_qty, SUM(orderedUnits - customerReturns) AS actual_sold_qty FROM Cocoblu_RZ_Sales GROUP BY Order_Date, asin ), Asin_Sku AS ( SELECT UPPER(TRIM(CAST(Channel_Product_Id AS STRING))) AS asin, UPPER(TRIM(CAST(SKU_Code AS STRING))) AS sku FROM `zouk-wh.MapleMonk.zouk_unicommerce_get_product_listing` WHERE Channel_Product_Id IS NOT NULL AND SKU_CODE IS NOT NULL QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(CAST(Channel_Product_Id AS STRING))) ORDER BY UPPER(TRIM(CAST(SKU_Code AS STRING))) ) = 1 ), Costmaster_History AS ( SELECT UPPER(TRIM(ASIN)) AS ASIN, UPPER(TRIM(WMS_SKU)) AS WMS_SKU, BAU, NLC, Cost_Price, snapshot_date FROM `zouk-wh.MapleMonk.finance_pricemaster_ccogs_retail_ez_History` WHERE NLC IS NOT NULL AND NLC > 0 ), GST_Master AS ( SELECT sku, MAX(IF(rate_raw >= 1, rate_raw / 100, rate_raw)) AS GST_Tax_Type_Code FROM ( SELECT UPPER(TRIM(CAST(Product_Code AS STRING))) AS sku, SAFE_CAST( REGEXP_EXTRACT(CAST(GST_Tax_Type_Code AS STRING), r\'\d+(?:\.\d+)?\') AS FLOAT64 ) AS rate_raw FROM `zouk-wh.MapleMonk.Zouk_Unicommerce_get_product_master` ) WHERE sku IS NOT NULL AND sku <> \'\' GROUP BY sku ), Cocoblu_RZ_Base AS ( SELECT m.asin, k.sku, m.Order_Date, COALESCE(SAFE_CAST(s.BAU AS FLOAT64), 0) AS BAU, SAFE_CAST(s.NLC AS FLOAT64) AS NLC, SAFE_CAST(s.Cost_Price AS FLOAT64) AS NLC_wo_tax, 0.22 AS trade_margin_pct, m.total_value, m.total_qty, m.actual_sold_qty, s.snapshot_date AS cost_snapshot_date, COALESCE( SAFE_DIVIDE(m.total_value, NULLIF(m.total_qty, 0)), 0 ) AS asp_without_tax FROM Daily_Sales m LEFT JOIN Asin_Sku k ON m.asin = k.asin LEFT JOIN Costmaster_History s ON s.ASIN = m.ASIN QUALIFY ROW_NUMBER() OVER ( PARTITION BY m.asin, m.Order_Date ORDER BY IF(s.snapshot_date <= m.Order_Date, 0, 1), ABS(DATE_DIFF(s.snapshot_date, m.Order_Date, DAY)) ) = 1 ), Cocoblu_RZ_With_GST AS ( SELECT b.*, COALESCE(g.GST_Tax_Type_Code, 0.05) AS GST_Tax_Type_Code FROM Cocoblu_RZ_Base b LEFT JOIN GST_Master g ON b.sku = g.sku ), Final_Cocoblu_RZ_CCOGS AS ( SELECT asin, sku, Order_Date, BAU, NLC, NLC_wo_tax, trade_margin_pct, GST_Tax_Type_Code, total_value, total_qty, actual_sold_qty, cost_snapshot_date, asp_without_tax, asp_without_tax * (1 + GST_Tax_Type_Code) AS asp_with_tax, asp_without_tax * (1 + GST_Tax_Type_Code) * (1 - trade_margin_pct) AS unit_cost_less_margin, SAFE_DIVIDE( asp_without_tax * (1 + GST_Tax_Type_Code) * (1 - trade_margin_pct), 1 + GST_Tax_Type_Code ) AS unit_cost_without_tax, NLC_wo_tax - SAFE_DIVIDE( asp_without_tax * (1 + GST_Tax_Type_Code) * (1 - trade_margin_pct), 1 + GST_Tax_Type_Code ) AS ccogs_per_unit, BAU * actual_sold_qty AS bau_sec_sales FROM Cocoblu_RZ_With_GST ), Month_Avg_CCOGS AS ( SELECT asin, DATE_TRUNC(Order_Date, MONTH) AS ccogs_month, SAFE_DIVIDE( SUM(ccogs_per_unit * actual_sold_qty), SUM(actual_sold_qty) ) AS ccpu_month_avg FROM Final_Cocoblu_RZ_CCOGS WHERE total_qty > 0 AND asp_without_tax > 0 AND actual_sold_qty > 0 GROUP BY asin, DATE_TRUNC(Order_Date, MONTH) ), Asin_Avg_CCOGS AS ( SELECT asin, SAFE_DIVIDE( SUM(ccogs_per_unit * actual_sold_qty), SUM(actual_sold_qty) ) AS ccpu_asin_avg FROM Final_Cocoblu_RZ_CCOGS WHERE total_qty > 0 AND asp_without_tax > 0 AND actual_sold_qty > 0 GROUP BY asin ), Adjusted_CCOGS AS ( SELECT f.Order_Date, f.asin, f.actual_sold_qty, CASE WHEN f.actual_sold_qty < 0 THEN COALESCE(m.ccpu_month_avg, a.ccpu_asin_avg, 0) WHEN f.total_qty > 0 AND f.asp_without_tax > 0 THEN COALESCE(f.ccogs_per_unit, 0) ELSE 0 END AS ccogs_per_unit_adj FROM Final_Cocoblu_RZ_CCOGS f LEFT JOIN Month_Avg_CCOGS m ON f.asin = m.asin AND DATE_TRUNC(f.Order_Date, MONTH) = m.ccogs_month LEFT JOIN Asin_Avg_CCOGS a ON f.asin = a.asin ), Daily_CCOGS AS ( SELECT \'AMAZON_RETAIL_EZ_\' AS channel_name, Order_Date AS ccogs_date, SUM(ccogs_per_unit_adj * actual_sold_qty) AS ccogs FROM Adjusted_CCOGS GROUP BY Order_Date ) SELECT channel_name, ccogs_date, ccogs FROM Daily_CCOGS ) AS source ON target.channel_name = source.channel_name AND target.ccogs_date = source.ccogs_date WHEN MATCHED THEN UPDATE SET target.ccogs = source.ccogs WHEN NOT MATCHED THEN INSERT (channel_name, ccogs_date, ccogs) VALUES (source.channel_name, source.ccogs_date, source.ccogs);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            